'use strict';
// Instructions are filtered on the server with the same module/action checks as the app.
const allow=(module,action='VIEW')=>({all:[[module,action]]});
const step=(title,body,check,access)=>({title,body,check,access});
const lesson=(id,title,category,level,minutes,summary,simple,access,steps,extra={})=>({id,title,category,level,minutes,summary,simple,access,steps,...extra});
const recordView={any:['DOCUMENTS','CLIENTS','ITEMS','UNITS','ACCOUNTS','PROJECTS','JOURNALS','CREDIT_NOTES'].map(m=>[m,'VIEW'])};
const lessons=[
lesson('welcome','Introduction','Start here','Beginner',5,
 'Understand your workspace, your access and the safest way to start.',
 'Pehle sahi business check karein. Phir apne access wale module se kaam shuru karein.',null,[
 step('Confirm the business before doing anything','The organization selector in the top bar identifies the active business. A business is a separate workspace for its customers, documents and accounting. If you have more than one membership, choose the intended workspace before opening a record.','The name in the selector matches the business you intend to work on.'),
 step('Find information in the documentation','Browse the feature groups in the sidebar, use search for a task such as payment or GSTIN, or follow the next-page links to read in order. The documentation shows only articles and action instructions allowed by your current permissions.','Search results and topic navigation contain only the features permitted for your account.'),
 step('Learn without changing business data','Training screenshots contain fictional sample values. They do not create invoices, post journals or upload files. Related app links leave the documentation and open the real application; changes there follow normal save and permission rules.','You can tell the difference between a guide exercise and a real form.'),
 step('Finish one small task, then verify it','Read the expected result after every step. Check the saved record rather than relying on a button click. Use On this page to jump to a specific section. Saved page bookmarks are remembered in this browser for your account and workspace.','You know where the result should appear and can explain what changed.')
],{screen:'workspace',outcome:'Recognize the active workspace, find a permitted feature and follow an instruction safely.',notes:[['Permission-specific documentation','Chapters and action steps follow your effective permissions, not just the name of your role. Reload the guide after an owner changes access.'],['Access and approvals','Reading documentation or saving a bookmark never grants permissions, changes records or certifies accounting approval.']]}),
lesson('profile','Profile and account security','Start here','Beginner',4,
 'Update your personal details, preview a photo and protect your sign-in.',
 'Photo choose karne se upload save nahi hota. Preview check karke Save Profile Details dabayein.',null,[
 step('Open My Profile','Open your account menu at the top right and choose My Profile. Your personal name and photo are separate from the organization’s legal name, branding and invoice defaults.','The page title is My Profile and the personal account is yours.'),
 step('Choose and preview a photo','Choose image accepts PNG, JPEG or WebP up to 2 MB. The preview changes locally before a save. Undo selection restores the current saved photo; it does not delete that saved image. A rejected file leaves the previous photo in place.','The preview is the image you want and the filename says it is ready to save.'),
 step('Save personal details','Check your name, email and phone, then select Save Profile Details once. Wait for the result. If a field is invalid or the email is already used, correct the reported issue. On a failed save, entered fields remain available and the save button becomes usable again.','Reload My Profile and confirm the saved name, contact details and photo.'),
 step('Change a password deliberately','Use your current password, a new password of at least eight characters and an identical confirmation. A longer unique password is preferable. Never send your password to a teammate or include it in an error screenshot. A profile edit cannot promote your own role.','A success message confirms the password change; a permission badge is not editable from this form.')
],{screen:'profile',links:[['Open My Profile','/profile']],outcome:'Maintain your own account without accidentally changing business identity.',notes:[['Saving and refreshing a profile photo','Selection only changes the local preview. Save the profile successfully, then refresh other already-open tabs if needed.'],['Undoing an image selection','Undo cancels the newly selected file and restores the saved photo or default avatar. It does not delete a saved image.']]}),
lesson('navigation','Navigation, themes and finding your work','Start here','Beginner',4,
 'Use search, tables, focus states and theme preferences confidently.',
 'Search ka result access ke hisaab se aata hai. Theme ka apna choice browser yaad rakhta hai.',null,[
 step('Find a page or record','The sidebar groups modules. Global search in the top bar helps find permitted commands and matching records. Use Ctrl+K to focus search where available. Results still require access; a missing result does not mean the record was deleted.','Open the intended result and check its record title and workspace.'),
 step('Understand two kinds of search','A page filter queries the relevant list. A shared DataTable may also have a local search box; Search this page searches only records already loaded for a server-paginated list. Clear both filters before concluding that a record is missing.','The displayed date range, status, search query and page number explain the visible rows.'),
 step('Choose your appearance','Without an explicit choice the app follows the device’s light/dark preference. The top-bar theme button saves an explicit light or dark choice in this browser. Device changes do not override that explicit choice. Different browsers or devices can have separate preferences.','Reload a page and confirm the chosen theme remains.'),
 step('Use keyboard and loading feedback','Tab moves between controls, Enter activates a focused link or button, and Escape closes supported dialogs. Focus rings identify the active control. Skeletons or progress indicators mean a request is in progress; do not repeatedly submit the same operation.','You can navigate a form and recognize loading, success and failure states.')
],{screen:'workspace',outcome:'Find records accurately and distinguish loading from an empty result.',notes:[['Server filters and table search','One may query the server while the table search filters currently loaded rows. The Search this page label identifies the latter.'],['Action availability','Your permission, the record status or a closed period may prevent the action. Refresh first, then ask an owner to check access.']]}),
lesson('records','Open, edit and understand record history','Daily work','Beginner',6,
 'Read a record, make permitted edits and inspect the history safely.',
 'Row kholkar details check karein. Edit tabhi milega jab permission aur record status dono allow karein.',recordView,[
 step('Open the record workspace','On supported lists, click a row or focus it and use Enter. A detail dialog shows the record’s values. Some action links intentionally open a dedicated page instead. Always check the title and reference before editing.','The detail heading matches the row you intended to open.'),
 step('Read status before changing anything','Active/inactive controls are not the same as payment or accounting status. A VOID, CLOSED, DELETED, CANCELLED or ARCHIVED record can have additional restrictions. A read-only dialog is valid behaviour when the workflow is locked.','You understand whether the record is editable and why a dedicated workflow might be required.'),
 step('Inspect Edit history','Choose Edit history where available. Entries identify the actor, time and recorded action. Newer edits may include before/after field snapshots. Older activity can have no field snapshot; the guide cannot reconstruct data that was never recorded.','You can distinguish an actual field change from a historical activity entry without a snapshot.'),
 step('Make a permitted edit','If Edit is offered, change only the intended fields, review them and choose Save changes once. Some complex documents use an embedded or dedicated editor. If another person changed the record first, reload and review the latest version before trying again. Never overwrite a conflict blindly.','The dialog or refreshed list shows the saved values and, when captured by that workflow, a new history entry.',{any:['CLIENTS','ITEMS','UNITS','DOCUMENTS','PROJECTS','ACCOUNTS'].map(m=>[m,'EDIT'])})
],{screen:'history',outcome:'Explain what changed, who changed it and what historical evidence is actually available.',pitfalls:['Do not assume every table row has the same editor; specialised financial records use dedicated workflows.','Cancelling an edit discards unsaved input. It does not reverse an already saved update.']}),
lesson('dashboard','Read the business dashboard','Sales','Beginner',5,
 'Understand KPIs, trends, empty charts and the difference between revenue and cash.',
 'Invoice value aur bank me aaya paisa ek cheez nahi hain. Period aur workspace pehle check karein.',allow('DASHBOARD'),[
 step('Start with the selected period','The dashboard defaults to the current financial year. Use quick ranges or custom dates to ask a specific question. The current FY label identifies the calendar context; the chosen from/to dates define a custom analysis.','The period matches the business question rather than an accidental previous filter.'),
 step('Separate invoiced value from collected money','Invoiced totals describe documents. Collections describe receipt activity. Outstanding and overdue figures describe amounts not yet settled. A quotation is an offer and should not be treated as cash received. Review the relevant records before drawing a conclusion from a KPI.','You can explain why invoice value and collections can differ.'),
 step('Use charts as starting points','Revenue trends compare periods, quotation charts show pipeline activity, and ageing groups outstanding balances. Empty charts show No data to show rather than implying a technical error. Add activity only when appropriate or widen the reporting period.','A zero or empty chart is checked against filters and source records.'),
 step('Refresh without duplicating work','Refresh reloads metrics. Loading skeletons are temporary and should disappear after the request. If a server error appears, retain its reference ID and report what range and business were selected.','A refresh changes the display, not the underlying financial records.')
],{links:[['Open dashboard','/dashboard']],outcome:'Read the dashboard as a summary, not as a substitute for checking financial documents.'}),
lesson('clients','Customer records and document snapshots','Masters','Beginner',6,
 'Maintain reusable customer identity while preserving document history.',
 'Customer master badalne se purane invoice ka snapshot apne aap nahi badalta.',allow('CLIENTS'),[
 step('Find and inspect a customer','Open Clients and search by name or the identifiers supported by the page. Open a row to check contact details, GSTIN, state code, billing/shipping addresses and active status. Similar names are possible, so compare more than the display name.','You have identified the intended customer, not a similarly named account.'),
 step('Create a reusable customer','Choose New Client. Enter the customer name and the information you actually know. Check the GSTIN and state code for consistency when supplied. Avoid invented contact details. Save and reopen the record to verify the master data.','The new customer appears in the directory and can be selected on a new document.',allow('CLIENTS','CREATE')),
 step('Update the correct address','Use the permitted Edit action for the customer. Billing identifies invoicing information; shipping identifies the delivery address. If they differ, keep both rather than replacing one with the other. Check active status if the customer is unavailable in a new-document selector.','The customer master shows the intended contact and address values.',allow('CLIENTS','EDIT')),
 step('Understand historical snapshots','Documents keep their own saved customer details so later master edits do not silently rewrite old commercial records. Review a new document after selecting a saved customer. Correct an existing document only through its own permitted edit workflow.','You know whether you are changing master data or a particular document.')
],{screen:'clients',links:[['Open Clients','/clients']],outcome:'Reuse accurate customer information and keep historical documents understandable.',notes:[['Historical document snapshots','Its saved snapshot preserves the details used on that document. A customer-master edit is not a retrospective invoice edit.'],['Customer selection scope','Check active status, workspace and saved filters. A record in another business will not be offered.']]}),
lesson('suppliers','Suppliers and vendor identity','Masters','Beginner',4,
 'Identify the vendor correctly before a purchase or supplier bill.',
 'Supplier se kharidte hain; customer ko bechte hain. Dono ki identity mix na karein.',allow('CLIENTS'),[
 step('Review the supplier directory','Open Suppliers. Search with a name, code, GSTIN, email or phone supported by the page. Inspect the record before linking it to a purchase. Customer and supplier roles represent different relationships even if the same legal entity is involved.','The vendor identity matches the intended purchase.'),
 step('Create a supplier','Choose Add Supplier, enter the available contact and tax details, and save. Verify addresses and GSTIN against the information provided by the vendor. An internal code identifies the supplier in this workspace.','The supplier is available to the purchase editor.',allow('CLIENTS','CREATE')),
 step('Keep vendor information current','Use Edit when permitted. Confirm that changing active status will not prevent a colleague from selecting the supplier for new work. Existing purchase/bill snapshots need their own review; do not assume a master update rewrites them.','The saved supplier is accurate and the effect on new selection is understood.',allow('CLIENTS','EDIT'))
],{links:[['Open Suppliers','/suppliers']],outcome:'Use the correct vendor master and avoid duplicate or misidentified suppliers.'}),
lesson('items-units','Items, units and repeatable line items','Masters','Beginner',5,
 'Make quantities, rates and tax classification understandable.',
 'Quantity ka matlab unit ke saath clear hota hai: 5 PCS aur 5 HRS alag hain.',{any:[['ITEMS','VIEW'],['UNITS','VIEW']]},[
 step('Read an item carefully','An item identifies what is sold, purchased or tracked. Check its description, unit, rate and HSN/SAC fields where supplied. A unit tells the reader whether a quantity means pieces, hours, kilograms or another measure.','A colleague can interpret the quantity without guessing.'),
 step('Maintain the item catalogue','Open Items when your access allows it. Add an item with a clear name and meaningful default values. A default is a starting point; check the actual rate and quantity on every commercial document.','The saved item is recognizable and its defaults are suitable for reuse.',allow('ITEMS','CREATE')),
 step('Maintain units deliberately','Open Units when permitted. Use a short symbol and a descriptive name. Before changing a unit, check dependent records. Do not rename a unit to change the meaning of historical quantities; use an appropriate separate unit instead.','The symbol and name describe the same measurement.',allow('UNITS','CREATE')),
 step('Check the selected unit on the document','A rate is usually expressed per selected unit. A quantity of 2 HRS at a rate of 1,000 has a different meaning from 2 PCS at that rate. Review descriptions and units together before a save.','The line quantity, unit and rate form one coherent statement.')
],{outcome:'Avoid unit mistakes that can make a mathematically correct total commercially wrong.',links:[{label:'Open Items',href:'/items',access:allow('ITEMS')},{label:'Open Units',href:'/units',access:allow('UNITS')}] }),
lesson('document-basics','Quotation, invoice and document lifecycle','Sales','Beginner',6,
 'Understand the promise, the bill and the different meanings of status.',
 'Quotation offer hai. Invoice bill hai. Payment alag receipt hai.',allow('DOCUMENTS'),[
 step('Know which document you are reading','A quotation proposes goods/services and commercial terms. An invoice records the billing document. Conversion connects a quotation to an invoice; it is not the same as recording a customer payment. Check the type badge and reference number first.','You can distinguish an offer from a bill.'),
 step('Use the document list filters','Open Documents. Choose type, lifecycle/payment status, search and date range as needed. Current FY is the default for the main period. Search the correct business and period before assuming a document is missing.','The visible list matches the intended document type and time range.'),
 step('Read amounts and addresses as a saved snapshot','Open a document to review line items, totals, billing/shipping details and terms. These values belong to that saved version. A later change to an item or customer does not automatically change the historical snapshot.','The saved document tells a consistent story about what was agreed or billed.'),
 step('Distinguish lifecycle from settlement','Active/inactive, converted and void describe different lifecycle situations. Paid/partially paid/outstanding relate to settlement. A voided document is not corrected by merely editing a customer master or recording another receipt.','You know whether the next question is about document validity or money collection.')
],{screen:'documents',links:[['Open Documents','/documents']],outcome:'Choose the right document and interpret its status before taking action.',glossary:[['Quotation','A commercial offer; it is not proof that money was received.'],['Invoice','The billing document containing the saved customer, items, tax and total.'],['Snapshot','The values saved on one document, preserved independently of later master changes.']]}),
lesson('create-document','Create a quotation or invoice accurately','Sales','Beginner',9,
 'Work through customer, addresses, lines, tax, terms and final verification.',
 'Pehle type aur date, phir customer, items aur totals. Save ke baad detail view zaroor check karein.',allow('DOCUMENTS','CREATE'),[
 step('Choose the type and transaction date','Start a new quotation or invoice using the intended action. Confirm the business and transaction date. The application resolves the financial year from that date. A closed financial year blocks new postings; choosing a reporting range does not change a transaction’s own date.','Type, business and date are correct before adding commercial details.'),
 step('Choose a saved customer or enter the document details','A saved customer can prefill name, contact and address fields. Review the copied values; they become the document snapshot. A selected project can link the document to project revenue where that workflow is used. Keep shipping separate when delivery differs from billing.','The document identifies the actual buyer and delivery location.'),
 step('Add meaningful line items','Choose or enter an item, add a clear description, quantity, unit and rate, and review any line-level discounts. Do not use zero quantity as a workaround for a missing price. Remove an unwanted line using its remove control.','Each line has an understandable commercial meaning and a valid quantity.'),
 step('Check tax and totals','Review GSTIN/state/place-of-supply inputs and the resulting CGST/SGST or IGST split. The server recalculates totals; a typed or displayed client-side amount is not authoritative. For example, 2 units at 1,000 each with a 10% line discount gives a taxable value of 1,800. At a chosen 18% tax rate, tax is 324 and the total is 2,124. This explains arithmetic and does not choose the correct tax treatment for your business.','The taxable value, discount, tax and final total reconcile with the intended lines.'),
 step('Read terms, save once and verify','Check remarks and terms before using Save. Wait for success. Reopen the saved record and verify its number, dates, customer, items and total. Numbering may be assigned by the server; do not replace it with an unrelated manual reference.','The saved document has the intended values and an assigned reference number.')
],{screen:'editor',links:[['New quotation','/documents/new?type=QUOTATION'],['New invoice','/documents/new?type=INVOICE']],outcome:'Create a document that is commercially clear and consistent with server-calculated totals.',pitfalls:['Changing the reporting period does not backdate or move a transaction.','Selecting a customer is not a substitute for reviewing its copied addresses.','Do not submit again while a save request is in progress.']}),
lesson('edit-convert','Edit, copy and convert documents','Sales','Intermediate',7,
 'Choose between updating a version, copying a draft and converting an accepted offer.',
 'Edit purane record ko update karta hai. Copy naya unsaved draft hai. Convert quotation se linked invoice banata hai.',allow('DOCUMENTS'),[
 step('Review before editing','Check type, lifecycle status and existing relations first. Inactive, void, deleted, converted or period-locked records can have different permitted actions. An unavailable action should be investigated instead of bypassed.','You know which operation is appropriate for the record.'),
 step('Edit with version awareness','Open Edit when offered, review the saved snapshot and submit the intended changes. A version conflict means another save happened after the version you opened. Reload, compare the latest record and repeat only the necessary edit.','The saved version and its history reflect the intended update.',allow('DOCUMENTS','EDIT')),
 step('Use Copy for genuinely new work','A copy is a new unsaved template, not an edit of the original. Review customer details, dates, lines and terms. Do not assume copied values are correct for the new transaction or that lifecycle/payment state should carry forward.','The new draft is checked independently before saving.',allow('DOCUMENTS','CREATE')),
 step('Convert an accepted quotation','Use Convert only for an eligible quotation when you intend to create a linked invoice. Review the result and the source relation. Repeated conversion is rejected so the same quotation does not generate duplicate invoices through that action.','The quotation and generated invoice show the conversion relationship.',allow('DOCUMENTS','CONVERT'))
],{links:[['Open Documents','/documents']],outcome:'Avoid duplicate invoices and accidental overwrites while preserving version history.'}),
lesson('document-corrections','Void, delete and commercial corrections','Sales','Advanced',6,
 'Understand why financial correction is different from changing a normal master record.',
 'Galat financial record ko chupane ke liye delete na karein. Status aur approved correction workflow samjhein.',allow('DOCUMENTS'),[
 step('Identify the mistake first','Write down which record is wrong, what the correct result should be and whether payments or linked documents exist. Review the record history and the relevant period. Correcting a tax or accounting document can require an authorised adjustment rather than a cosmetic text edit.','The intended correction has a specific reason and target.'),
 step('Void only when permitted and appropriate','Use the dedicated Void action on an eligible record. Read the confirmation and check dependent effects. Void is a lifecycle correction with an audit consequence; it is not the same as marking a record paid.','The record shows its resulting status and no unintended duplicate correction was created.',allow('DOCUMENTS','VOID')),
 step('Treat deletion as consequential','Use Delete only if the application allows it and your organisation’s process approves it. Do not assume every delete has a restore screen or is reversible. Read the confirmation and dependency errors. Repeated attempts do not remove a legitimate restriction.','You understand the available recovery path before confirming deletion.',allow('DOCUMENTS','DELETE')),
 step('Keep a correction trail','Preserve the reason, reference and follow-up action. If a period is closed or a relation blocks the action, involve the authorised colleague rather than changing unrelated dates to bypass the restriction.','Someone reviewing the record later can understand the correction.')
],{outcome:'Choose an authorised correction instead of trying to hide a financial mistake.'}),
lesson('customer-payments','Customer receipts and outstanding balances','Sales','Intermediate',7,
 'Record a receipt against the correct invoice and understand clearing and voiding.',
 'Payment ko sahi invoice se link karein. Overpayment aur double-click se bachhein.',allow('PAYMENTS'),[
 step('Check the invoice and its outstanding amount','A receipt settles an eligible invoice, not a quotation. Review the customer, reference, date, total, existing receipts and outstanding balance. Cash actually received must be distinguished from an unconfirmed intention to pay.','The invoice and the received amount belong together.'),
 step('Record the receipt','Use the supported payment action for the invoice. Enter the payment date, method, amount and reference accurately. The server checks the invoice balance and concurrent receipts; an amount above the outstanding balance is rejected. Wait for one result before retrying.','A receipt is saved with its own reference and the invoice balance updates.',allow('PAYMENTS','CREATE')),
 step('Understand a pending or cleared receipt','A payment method or clearing workflow may require an additional state transition before it is considered realised. Use the application’s status and supporting evidence, not a verbal assumption. Review the receipt detail when totals seem different.','You can explain the recorded status and the supporting reference.'),
 step('Correct an incorrect receipt through its workflow','Use Void only when the record and your permission allow it. Check the invoice’s outstanding balance after correction. Do not record an opposite or duplicate payment just to make a display look right.','The correction and resulting balance are consistent.',allow('PAYMENTS','VOID'))
],{outcome:'Reconcile recorded receipts with invoices without duplicate settlement.',pitfalls:['A quotation is not a valid target for invoice settlement.','A payment reference should identify real receipt evidence, not contain a password or banking credential.']}),
lesson('document-output','Print, PDF and spreadsheet outputs','Sales','Intermediate',5,
 'Choose the right output and verify what leaves the application.',
 'Preview, PDF aur Excel ka purpose alag hai. Share karne se pehle data aur period verify karein.',{any:[['DOCUMENTS','PRINT'],['DOCUMENTS','EXPORT']]},[
 step('Check the saved version first','An output represents the saved document or selected records, not unsaved changes left in an editor. Confirm the reference, type, customer, date, items, total and selected template before generating it.','The source is the version you intend to share.'),
 step('Print a document','Use the document Print action when permitted. Inspect the browser print preview, paper size, page breaks, long descriptions and footer. A preview is a chance to detect layout mistakes before issuing a copy.','The printed pages contain all intended lines and totals.',allow('DOCUMENTS','PRINT')),
 step('Download a PDF','Use the available PDF download/export action. The application generates the file from the saved document and selected/default layout. Open the resulting file and check its reference, customer, totals and page breaks before sharing it.','The PDF is readable and represents the intended saved record.',allow('DOCUMENTS','EXPORT')),
 step('Export a filtered list','Apply the intended type, status, search and dates before using the Excel export. Open the downloaded spreadsheet and verify its scope. Treat exported customer and financial information as private business data.','The exported list matches the question you intended to answer.',allow('DOCUMENTS','EXPORT')),
 step('Remember that a downloaded file is separate','Changing a template or saved document later does not rewrite a PDF or spreadsheet already downloaded. Regenerate a checked output when a new version is required, and avoid confusing older files with the new one.','The file you share is the intended version.')
],{outcome:'Produce the correct output without sharing an old or wrongly filtered file.'}),
lesson('credit-notes','Credit and debit notes','Sales','Intermediate',6,
 'Read adjustments and understand the difference between a note and a cash movement.',
 'Credit/debit note adjustment hai; cash refund ya receipt ka record alag ho sakta hai.',allow('CREDIT_NOTES'),[
 step('Identify the adjustment','Open Credit & Debit Notes. Read the type, date, party, related document, reason and amounts. A note adjusts a commercial/accounting position; it is not automatically evidence that cash moved.','The adjustment can be linked to a clear business reason.'),
 step('Create a justified note','Use the permitted creation workflow. Choose the correct note type and party/document relationship, enter the reason and review line/tax values before saving. A closed period can prevent posting.','The saved note has the intended type, reference and amount.',allow('CREDIT_NOTES','CREATE')),
 step('Review before print or export','Check all saved details and the relation to the original transaction. Use available print/export actions only after verification.','The issued output matches the saved adjustment.'),
 step('Use a dedicated correction','If a note is wrong, use its permitted edit/void workflow where available. Avoid compensating adjustments with unclear reasons.','The correction is traceable and the final position is understandable.',allow('CREDIT_NOTES','VOID'))
],{links:[['Open Credit & Debit Notes','/credit-debit-notes']],outcome:'Recognize an adjustment and preserve a clear reason and reference.'}),
lesson('purchasing','Purchase order, goods receipt and supplier bill','Purchasing','Beginner',8,
 'Follow the difference between an order, goods received and money owed.',
 'PO = kya mangaya. GRN = kya mila. Supplier bill = kitna dena hai.',allow('DOCUMENTS'),[
 step('Read the procurement chain','A purchase order describes a commitment to a supplier. A goods receipt records what arrived. A supplier bill records the vendor’s billing claim. These records answer different questions and should not be treated as interchangeable proof.','You can explain order, receipt and bill separately.'),
 step('Create a purchase order','Use New Purchase Order, choose the supplier and review date, project, lines, quantities, units, rates and terms. Save once and inspect the resulting order.','The order states what should be supplied and under what terms.',allow('DOCUMENTS','CREATE')),
 step('Record only what arrived','Open an eligible order’s receiving workflow. Enter the received quantities and supporting delivery information. Partial receipt is different from full receipt. Repeated submissions are guarded, and received quantity cannot exceed the permitted remaining quantity.','The receipt detail and the order’s remaining quantity reconcile.',allow('DOCUMENTS','EDIT')),
 step('Review the goods receipt','Open Goods Receipts (GRN) to inspect the received items and source order. Keep the supplier’s delivery/challan reference distinct from the internal receipt number.','The record proves what was received, without pretending to prove that a bill was paid.'),
 step('Inspect the supplier bill independently','Compare the vendor bill with the supplier, order/receipt evidence and amounts. A purchase order alone does not prove the final supplier claim or its payment.','Any difference between ordered, received and billed values is investigated before further action.')
],{links:[['Purchase Orders','/purchases/orders'],['Goods Receipts','/purchases/receipts'],['Supplier Bills','/purchases/bills']],screen:'documents',outcome:'Follow procurement without confusing a promise, a physical receipt and a payable.'}),
lesson('supplier-bills','Supplier bills and vendor payments','Purchasing','Intermediate',7,
 'Keep the vendor invoice reference, internal bill and settlement distinct.',
 'Vendor ka invoice number aur app ka internal number alag ho sakta hai. Dono verify karein.',allow('DOCUMENTS'),[
 step('Read the bill and its evidence','Open Supplier Bills and inspect the supplier, external invoice reference, internal number, bill/due dates, amount and verification status. Compare supporting order/receipt evidence where linked.','You can identify the vendor’s original reference and the internal record separately.'),
 step('Create a supplier bill carefully','Choose New Supplier Bill. Enter the supplier, actual bill date, reference and lines. Quantities must be valid; zero is not silently converted to one. Review taxable value and tax before saving once.','The saved bill matches the supplier’s claim and intended project/business.',allow('DOCUMENTS','CREATE')),
 step('Record vendor settlement through the supported integration','Vendor payment operations currently have API endpoints rather than a dedicated standalone menu screen. An authorised integration can use POST /api/supplier-payments and read the saved result. It must provide the correct bill/supplier relationship, payment date, amount, method and reference accepted by the API. This guide does not send a payment or execute an API request.','A supported integration verifies the payment record and remaining payable.',allow('DOCUMENTS','CREATE')),
 step('Use voiding for an authorised correction','A supplier bill or vendor payment may have its own Void operation. Check dependencies and resulting balances. Correcting an internal record is not a bank transfer or a cancellation at the vendor’s bank.','The application status, financial evidence and real-world settlement are reconciled.',allow('DOCUMENTS','VOID'))
],{links:[['Open Supplier Bills','/purchases/bills']],outcome:'Keep purchase evidence and settlement records accurate without assuming a bank transaction happened.'}),
lesson('expenses-income','Expenses and other income','Accounting','Beginner',6,
 'Classify everyday operating spend and other income consistently.',
 'Expense business ka kharcha hai. Other income ko sales invoice ke saath confuse na karein.',allow('ACCOUNTS'),[
 step('Choose the right register','Use Expenses for operating spend and Other Income for supported income outside the main sales-document workflow. Select the correct workspace and reporting range before reviewing totals.','The register matches the nature of the activity.'),
 step('Record an expense or other income','Open the relevant add dialog when permitted. Enter the actual transaction date, amount, category/source and a useful description. Link a project when the workflow supports and requires it. Check the entry before saving.','The new row has a meaningful description, correct date and intended amount.',allow('ACCOUNTS','CREATE')),
 step('Read the saved detail and summary','Open the supported row detail. Compare the individual amount with the selected period’s totals. Empty analysis indicates no matching activity; widen the range only if that matches the question you are asking.','The summary can be explained using its source records.'),
 step('Correct through permitted controls','Use available edit controls for an eligible record. History is available where the workflow captured it. If the date belongs to a closed period, stop and use the authorised correction process.','The saved entry and its audit context remain understandable.',allow('ACCOUNTS','EDIT'))
],{links:[['Open Expenses','/financials/expenses'],['Open Other Income','/financials/other-income']],outcome:'Record non-sales activity with useful classification and a verifiable date.'}),
lesson('reports','Choose the right accounting report','Reporting','Intermediate',8,
 'Ask a precise question and choose the report that answers it.',
 'Profit aur cash alag hain. Har report ka apna purpose aur date basis hota hai.',allow('REPORTS'),[
 step('Start with one business question','Use the Reports hub. Profit & Loss describes income/expense performance over a period. Balance Sheet describes a position as of a date. Trial Balance checks account debit/credit balances. General Ledger explains account movements; Journal Register lists accounting entries.','You can name the question before selecting the report.'),
 step('Set the correct date basis','Use a from/to period for activity reports and an as-of date for position reports where offered. An FY selection and a custom date range are not necessarily the same filter. Check the displayed dates and workspace before interpreting totals.','The report’s heading and filters describe the intended scope.'),
 step('Drill into source records','Use available references or detail controls to investigate an amount. Compare the source document, posting state and date. A total without context is not enough to identify a duplicate or an error.','A source record or ledger movement explains the value.'),
 step('Export a checked result','When an export action is permitted and available, apply filters first and then use the required output format. Check headings, period and totals in the exported file before sharing it. Exports can contain private financial information.','The downloaded output corresponds to the intended report and period.',allow('REPORTS','EXPORT'))
],{screen:'reports',links:[['Open Reports','/reports']],outcome:'Select a report by purpose and verify its scope before relying on its figures.',glossary:[['Profit & Loss','Performance over an interval; it is not the same as bank cash.'],['Balance Sheet','Assets, liabilities and equity at a selected point in time.'],['Trial Balance','Debit and credit account balances used to review accounting equilibrium.']]}),
lesson('workbench','Analyse one FY, many FYs and grouped datasets','Reporting','Intermediate',7,
 'Use the reporting workbench without confusing filters with data changes.',
 'From FY aur Through FY se multiple years analyse kar sakte hain. Isse transaction ki date nahi badalti.',allow('REPORTS'),[
 step('Choose a dataset','Open Analytics Workbench and select a dataset available to your account. Different datasets expose different fields and filters. A selected business scope must remain within the businesses you can access.','The dataset represents the activity you want to analyse.'),
 step('Select a period','From FY defines the first year and Through FY defines the last year. Custom From/To dates can span year boundaries. For example 1 April 2024 to 31 March 2027 spans three Indian financial years. Apply the range and confirm the URL/filter summary.','The dates match the intended interval and are in chronological order.'),
 step('Group to answer a question','Choose grouping such as business, month, status or party when offered for the dataset. Grouped results answer an aggregate question; flat results show underlying records. Do not add already-grouped totals to a separate flat total.','The grouping explains what one row represents.'),
 step('Inspect filters before an export','Search text, status, date range and scope can all restrict a result. Clear an unintended filter before concluding that activity is absent. Use the workbench export controls only after checking the selected dataset and scope.','The exported or displayed result answers the same question.')
],{screen:'reports',links:[['Open Analytics Workbench','/reports/workbench']],outcome:'Build a reproducible analysis across one or several years.'}),
lesson('customer-statements','Receivables, ageing and customer statements','Reporting','Intermediate',6,
 'Investigate what is owed and explain a customer account over a period.',
 'Ageing overdue balance ko buckets me batata hai. Statement customer ka period-wise account samjhata hai.',allow('REPORTS'),[
 step('Review the receivables position','Open Customer Receivables from Reports. Read the available cutoff/period and status fields before comparing balances. An ageing bucket groups an outstanding amount by age; it is not a new invoice or payment.','You understand what date and balance the ageing view represents.'),
 step('Choose the customer statement','Open Customer Statement and select the intended customer. Set the required period and review opening balance, movements and closing position where the report provides them. Identical customer names must be checked against the correct record and workspace.','The statement is for the intended customer and period.'),
 step('Trace a disputed amount','Follow available references into the invoice, receipt or adjustment. Compare dates, saved status and amounts. A missing clearance or a wrongly chosen reporting range may explain a difference; do not create a second receipt just to make a report agree.','Source evidence explains the movement or gives a precise issue to investigate.'),
 step('Export a checked statement','Use the permitted statement export, then verify customer, period and totals in the file. A statement can contain sensitive customer financial information, so share only through an authorised business process.','The exported statement matches the reviewed report.',allow('REPORTS','EXPORT'))
],{links:[['Customer Receivables','/reports/customer-receivables'],['Customer Statement','/reports/customer-statement']],outcome:'Explain a customer balance using the correct period and source transactions.'}),
lesson('financial-years','Automatic FYs and period controls','Accounting','Intermediate',7,
 'Understand annual rollover, current markers and why closed periods block changes.',
 'FY 1 April se 31 March tak hai. Naya FY automatically banega; purana FY apne aap close nahi hota.',allow('FINANCIAL_YEARS'),[
 step('Understand the Indian FY boundary','The current FY runs from 1 April through 31 March. The app ensures the current business’s FY during authenticated page use; a transaction also resolves its FY from its own date. At rollover the first page access or transaction creates the needed year, without manual creation.','The FY page shows the correct current period for this business.'),
 step('Distinguish current from open','Current identifies today’s calendar period. OPEN/CLOSED controls accounting eligibility. A historical year can be open for authorised work, and a current marker does not override a closed status. New-year creation does not silently post closing journals for the previous year.','You can explain why the current marker and status are separate.'),
 step('Review closing before approval','Use Close Year to inspect the preview and blockers. Earlier years with accounting activity may need to be closed first within this business. Review totals and consequences with your accounting process before executing a close.','The preview is understood before any accounting action.',allow('FINANCIAL_YEARS','CLOSE')),
 step('Reopen only with a reason','Use Reopen only with the required authority and a meaningful reason. Reverse chronological constraints can require later closed years to be reopened first in the same business. Reopening uses explicit accounting reversal behaviour rather than deleting history.','The reason and resulting period status are traceable.',allow('FINANCIAL_YEARS','REOPEN')),
 step('Handle initial opening balances carefully','Opening balances are an initial accounting workflow, not a tool for disguising routine transaction mistakes. Enter approved balances only through the allowed screen and check that debits and credits balance.','The initial journal and account balances match approved opening evidence.',allow('FINANCIAL_YEARS','MANAGE'))
],{links:[['Open Financial Years','/financial-years']],outcome:'Use automatic periods while preserving deliberate, auditable year-end controls.'}),
lesson('journals','Journals and double-entry controls','Accounting','Advanced',7,
 'Read and post balanced accounting entries through the permitted workflow.',
 'Debit aur credit total equal hone chahiye. Sirf balance banana accounting reason ka substitute nahi hai.',allow('JOURNALS'),[
 step('Read the journal first','Inspect reference, entry date, source type, narration, status and lines in the Journal Register. Source-generated entries belong to a business workflow; changing an unrelated master record will not rewrite their financial history.','You know what business event the entry represents.'),
 step('Prepare a justified entry','Use the permitted journal creation workflow and eligible posting accounts. Choose a valid date in an open FY, write a meaningful narration and enter approved debit/credit lines. Total debits must equal total credits. Do not add an unexplained balancing line.','The entry is both mathematically balanced and supported by a clear reason.',allow('JOURNALS','CREATE')),
 step('Check the posting result','Review the posted journal and related account movements. Draft intent and a posted entry are different states. If the request failed, do not assume any partial posting succeeded; check the authoritative record.','The saved status and ledger movements confirm what actually happened.'),
 step('Correct with the allowed reversal workflow','Use the dedicated void/reversal process when permitted. The reversal date must be eligible; a closed period can block it. Preserve the reason and relation to the original instead of deleting history.','The correction is linked and auditable.',allow('JOURNALS','VOID'))
],{outcome:'Read the reason behind an entry and respect balanced, period-locked posting controls.',links:[['Open Journal Register','/reports/journals']]}),
lesson('projects','Project workspace and daily execution','Projects','Beginner',7,
 'Connect delivery work, documents, tasks and evidence in one project context.',
 'Project ko hub samjhein: customer, documents, tasks aur evidence ek jagah milte hain.',allow('PROJECTS'),[
 step('Open the intended project','Use Projects and inspect its code, customer, status, dates and description. A project is a grouping for delivery and related records; it is not itself a payment receipt. Some financial values or tabs are hidden when your role cannot view them.','The project identity and visible scope match your assignment.'),
 step('Create a clear project','Choose New Project when permitted. Use a meaningful name, dates, customer and description. Review any available quotation-to-project workflow before creating a duplicate for the same job.','The project can be identified by the team without guessing.',allow('PROJECTS','CREATE')),
 step('Maintain tasks','Use the project’s task controls when available. Give each task a concrete outcome, dates and an understandable status. A task status describes execution; it should not be treated as proof that an invoice is settled.','The task list communicates what work remains.',allow('PROJECTS','CREATE')),
 step('Follow related records','Review the available documents, purchases, labour and attachment tabs. A tab can be empty because nothing is linked or because your access excludes part of the information. Check both before creating more records.','You understand which source record owns the information.')
],{links:[['Open Projects','/projects']],outcome:'Use the project as a context for work without mixing delivery status and settlement.'}),
lesson('project-costs','Project labour, materials and profitability','Projects','Advanced',8,
 'Capture costs with the right unit, source and approval.',
 'Hours, daily labour aur material movement alag cost sources hain. Ek hi cost do baar mat record karein.',allow('PROJECTS'),[
 step('Choose the right cost source','Timesheets record time; daily labour records a workforce/day cost; contractor orders describe subcontracted work; material issue/return records stock movement. Choose the correct source rather than entering the same expense through multiple paths.','A cost has one clear source and supporting evidence.'),
 step('Log time or daily labour accurately','Use the available project controls. Check worker/person, actual work date, hours or daily quantities, rate fields offered to your role and notes. A reporting range does not change the date of the cost.','The saved entry can be explained by an actual work event.',allow('PROJECTS','COST_CREATE')),
 step('Approve the right entry','Review supporting details before using an approval action. Approval is a separate responsibility from entering data. Do not approve only because the total looks plausible.','The entry’s status reflects a deliberate review.',allow('PROJECTS','APPROVE')),
 step('Issue and return materials consistently','Use the dedicated material issue/return controls. Verify item, quantity, unit, project and date. A return is related to physical stock movement; it is not merely a negative number typed into an unrelated expense.','Stock and project evidence explain the movement.',allow('PROJECTS','COST_CREATE')),
 step('Read profitability from source costs','Use the Financials tab/endpoint when authorised. Compare contract/revenue and the cost categories actually captured. Missing costs or unlinked documents can make a summary incomplete.','The summary is traced back to its component records.',allow('PROJECTS','FINANCIALS_VIEW')),
 step('Close a project after reviewing blockers','Use the closure preview and Close action when permitted. Confirm that work, linked activity and financial/process blockers have been addressed. Closing is not a way to hide unfinished records.','The resulting status and closure evidence match the intended handover.',allow('PROJECTS','CLOSE'))
],{links:[['Open Projects','/projects']],outcome:'Record each cost once and interpret profitability with its evidence.',pitfalls:['A timesheet total is not a customer invoice.','View permission alone does not imply access to budgets, rates or profitability.']}),
lesson('attachments','Project files, metadata and downloads','Projects','Intermediate',5,
 'Keep evidence identifiable and respect upload/download permissions.',
 'File ka title, category aur date useful rakhein. Password ya secret ko attachment me mat rakhein.',allow('PROJECTS','ATTACHMENT_VIEW'),[
 step('Inspect attachment metadata','In an accessible project, open the attachments area. Read title, category, original filename, issue/expiry dates and description where present. Metadata helps identify the correct evidence before downloading.','The file and project relationship are clear.'),
 step('Upload a supported file','Use the project upload control when permitted. Check the currently displayed file-type and size limits before selecting a file. Supply meaningful metadata and verify the saved attachment. Uploading to a wrong project is still a mistake even if the file itself is valid.','The correct project shows the intended filename and metadata.',allow('PROJECTS','ATTACHMENT_UPLOAD')),
 step('Download only authorised evidence','Use the protected download action. A direct file reference does not bypass permission or business checks. Treat downloaded documents as private business information.','The downloaded evidence is the file you intended to review.')
],{outcome:'Attach evidence that another person can identify and use without guessing.'}),
lesson('team','Team access and activity','Administration','Intermediate',7,
 'Understand memberships, roles, explicit permissions and audit activity.',
 'Role ka naam akela kaafi nahi: effective permissions decide karti hain ki user kya kar sakta hai.',allow('TEAM'),[
 step('Inspect the team context','Open Team and review the users available to your account. A platform role and a business membership are different concepts. Access can also depend on explicit permission configuration and active membership.','You know which workspace and person you are reviewing.'),
 step('Add or invite a teammate','Use the permitted team creation/invitation flow. Check the recipient identity, business access and intended role before submitting. Never share your own password to let someone work in the app.','The intended person receives or has the appropriate account/access state.',allow('TEAM','CREATE')),
 step('Change access conservatively','Use role/permission controls only with the required authority. Grant the least access needed for the job, review sensitive actions separately and verify the resulting state. A guide chapter becoming visible does not itself grant access.','The saved configuration matches the actual job responsibilities.',allow('TEAM','MANAGE')),
 step('Review activity with its limits','Use available activity views when authorised. Actor, time, module and target provide context, but older entries may lack field snapshots. Do not treat a missing snapshot as proof that nothing changed.','You can explain what the activity evidence does and does not show.',allow('TEAM','ACTIVITY_VIEW'))
],{links:[['Open Team','/team']],outcome:'Understand access as a controlled business responsibility, not a cosmetic role label.'}),
lesson('organization','Organization identity and numbering','Administration','Intermediate',7,
 'Keep legal identity, display branding and document references separate.',
 'Legal name official documents ke liye hai. Workspace name app branding ke liye. Dono ko soch kar badlein.',allow('SETTINGS'),[
 step('Distinguish personal and business identity','My Profile changes your own account. Organization settings change business identity and document defaults. Legal name, trade/display name and application/workspace name have different purposes.','You are editing the right kind of identity.'),
 step('Maintain legal and contact defaults','Use the permitted organization settings screen. Check legal name, GSTIN/state, registered address, contact details, bank/UPI information and document terms before saving. A value may be printed on future documents; a typo is not just a visual issue.','Saved defaults are correct for future work.',allow('SETTINGS','EDIT')),
 step('Upload and preview the organization logo','In Organization settings, choose a PNG, JPEG or WebP image up to 2 MB. The preview is local until you save the settings successfully. Undo selection restores the saved logo. An invalid image or failed save keeps the previous saved logo. Replacing a logo retains the previous uploaded file. The organization logo is separate from your personal profile photo.','After saving, reload settings and confirm the logo preview and business identity.',allow('SETTINGS','EDIT')),
 step('Understand numbering without changing history','References are generated by the application’s series rules. In the numbering screen, a prefix change affects future numbering behaviour; it does not reset historical counters or renumber existing documents. Read the uppercase/alphanumeric rule before saving.','The prefix and example format meet the stated rules.',{roles:['ADMIN']}),
 step('Manage multiple businesses deliberately','Organizations are separate workspaces. Switch to the correct business before reading or updating records. Adding or managing a business is an administrative workflow; do not create another workspace merely because a filtered list is empty.','The active business and accessible membership are confirmed.')
],{outcome:'Prevent branding and numbering mistakes from propagating into new documents.',links:[{label:'Organization settings',href:'/settings',access:allow('SETTINGS')},{label:'Numbering series',href:'/admin/numbering',access:{roles:['ADMIN']}}]}),
lesson('templates','Document templates and print appearance','Administration','Intermediate',7,
 'Choose an active layout, customise a copy and verify output.',
 'Template design badalta hai; customer, date aur amount actual document data se aate hain.',allow('SETTINGS'),[
 step('Understand the two defaults','In Settings → Document & Invoice Templates, the active invoice template and quotation template can be different. A gallery preview is sample output, not a real issued customer document.','You know which default applies to each document type.'),
 step('Preview before choosing','Open a template’s preview and inspect the invoice/quotation variation, longer item descriptions, totals and footer. A template that looks good on one short sample may need checking with the actual document layout.','The relevant content remains readable in the preview.'),
 step('Create or duplicate a custom template','Choose Create Custom Template or Duplicate. Enter a name, choose a base layout and font, set primary/subtle colors and choose visible columns/features. Save once. Customisation copies a layout; it does not require changing a built-in template.','The saved custom template appears in the gallery.',allow('SETTINGS','EDIT')),
 step('Apply and verify defaults','Choose the desired invoice and quotation templates and select Apply. Reopen or regenerate the relevant preview/output to check the result. An already downloaded PDF is a separate file and does not rewrite itself after a setting change.','The application’s selected defaults and newly generated output agree.',allow('SETTINGS','EDIT')),
 step('Use custom CSS only with care','Advanced CSS can change printable layout. Keep changes small, test both document types and check long descriptions and page breaks. A design setting is not a way to alter authoritative transaction totals.','New output remains legible and complete.',allow('SETTINGS','EDIT'))
],{outcome:'Change document appearance without confusing sample design and actual transaction data.',links:[['Open template settings','/settings']],screen:'templates',screenAccess:allow('SETTINGS','EDIT')}),
lesson('inventory-api','Inventory movements and API-only workflows','Integrations','Advanced',6,
 'Understand stock operations currently exposed through integration endpoints.',
 'API-only ka matlab dedicated menu screen abhi nahi hai. Is guide ka example production request nahi bhejta.',allow('ITEMS'),[
 step('Know what is available','Inventory movement and valuation operations currently expose API endpoints. Item maintenance is available in the app, and project material controls provide related workflows where authorised. There is no separate stock-register menu promised by this guide.','You know whether to use a visible project control or an authorised integration.'),
 step('Read stock information through an integration','GET /api/inventory/movements lists permitted movement records; GET /api/inventory/summary/:itemId and GET /api/inventory/valuation provide supported summary views. An integration must use the authenticated business context and obey response validation.','Returned records belong to the intended business/item.'),
 step('Record a real movement','An authorised integration can use POST /api/inventory/movements with the supported movement type, item, date, quantity and cost fields. Validate units and physical evidence first. Do not send exploratory stock writes to production.','The saved movement and resulting stock summary reconcile.',allow('ITEMS','CREATE'))
],{outcome:'Recognize supported integration capabilities without searching for a non-existent menu screen.'}),
lesson('payroll-api','Employee, payroll and reimbursement integrations','Integrations','Advanced',7,
 'Understand the boundaries of API-only people and payroll operations.',
 'Team login accounts aur payroll employee records alag concepts hain. Payroll approval actual financial action hai.',{any:[['TEAM','VIEW'],['ACCOUNTS','VIEW']]},[
 step('Separate app users from employee records','A Team login determines application access. A payroll employee record represents employment/payroll data. One does not automatically prove the other exists. These ERP payroll operations currently use API endpoints rather than a complete dedicated payroll menu.','You know which identity an integration is handling.'),
 step('Read employees and payslips through authorised integrations','GET /api/payroll/employees and GET /api/payroll/employees/:id expose permitted employee data; GET /api/payroll/entries/:entryId/payslip serves a supported payslip. Do not share someone’s payroll data outside authorised business use.','The employee and period are the intended ones.',allow('TEAM')),
 step('Maintain employees and reimbursement claims','POST /api/payroll/employees and POST /api/payroll/reimbursements are authorised creation operations. An integration must validate the current API contract, supporting evidence and business context. The guide does not submit claims.','The record is saved once with the intended person and evidence.',allow('TEAM','CREATE')),
 step('Review management controls','Salary-structure updates and reimbursement approval have separate management endpoints and permissions. Review supporting details before invoking them. Visibility of a chapter is not a substitute for approval authority.','The intended management operation and its authority are clear.',allow('TEAM','MANAGE')),
 step('Generate a payroll period','POST /api/payroll/periods/generate is a controlled integration operation. Check the employee inputs, period, configuration and output before any later approval. Do not assume a sample calculation represents your statutory obligations.','The generated period and entries match approved inputs.',allow('ACCOUNTS','CREATE')),
 step('Approve and post as separate decisions','Approval uses POST /api/payroll/periods/:id/approve; ledger posting uses POST /api/payroll/periods/:id/post. These require different authorities. Confirm the saved status after each and avoid repeating a posting request blindly.','The period’s status and accounting result are verified.',{all:[['ACCOUNTS','MANAGE'],['ACCOUNTS','CLOSE']]})
],{outcome:'Understand payroll integration boundaries and keep sensitive employee data controlled.'}),
lesson('troubleshooting','Resolve errors without losing work','Start here','Beginner',5,
 'Use validation messages, references and a reproducible support report.',
 'Error ka exact reason aur reference ID note karein. Password ya secret screenshot me na bhejein.',null,[
 step('Read the reason before retrying','A validation error asks you to correct input. A permission error asks for an access review. A version conflict asks you to refresh and compare. A closed-period error asks for an authorised accounting workflow. These are different problems.','You can classify the error instead of repeating the same request.'),
 step('Handle an expired session safely','If a page says the security token is missing/expired or requests sign-in, save a private note of unsaved non-sensitive work, refresh and sign in as needed. Reload the form before submitting again. Never disable security checks as a workaround.','A fresh authenticated form is used for the next attempt.'),
 step('Verify before retrying a network failure','A lost connection may happen after a request reached the server. Search for the resulting record or inspect its status first. A loader is not a reason to submit several identical financial operations.','You know whether the first attempt already succeeded.'),
 step('Send a useful support report','Record the error reference ID when shown, time, page/module, workspace, role, record reference and the exact sequence that produced the issue. Include a screenshot that hides passwords, banking credentials and unrelated personal data. Server-side logs can correlate a reference with the request.','Support has enough context to reproduce the issue without needing your password.')
],{outcome:'Recover deliberately and give support evidence that can be investigated.',notes:[['Empty results','Check business, FY/date range, status, search and current-page search. If they are correct, there may be no matching activity yet.'],['Disabled actions','A save may be in progress, the record may be locked, or the action may not be allowed. Wait for the result, then inspect the reason instead of forcing another request.'],['Business approvals and documentation','Documentation and bookmarks do not record business approvals. Use the relevant business workflow and its audit history to confirm an approval.']]})
];
